package com.example.campusmaintenance.entity;
import com.example.campusmaintenance.enums.*; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="maintenance_requests") public class MaintenanceRequest {
@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String title; @Column(nullable=false,length=1000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private Category category; @Enumerated(EnumType.STRING) @Column(nullable=false) private Priority priority; @Enumerated(EnumType.STRING) @Column(nullable=false) private RequestStatus status; @Column(nullable=false) private String studentName; @Column(nullable=false) private String room; @Column(nullable=false) private LocalDateTime createdAt; @Column(nullable=false) private LocalDateTime updatedAt;
public MaintenanceRequest(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Category getCategory(){return category;} public void setCategory(Category v){category=v;} public Priority getPriority(){return priority;} public void setPriority(Priority v){priority=v;} public RequestStatus getStatus(){return status;} public void setStatus(RequestStatus v){status=v;} public String getStudentName(){return studentName;} public void setStudentName(String v){studentName=v;} public String getRoom(){return room;} public void setRoom(String v){room=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;}
}
